function buildLetters(fk) {
  const SRC = SCRIPT_FONTS[fk] || SCRIPT_FONTS['mrs-saint-delafield'];
  const strokes = [], all = []; let total = 0;
  SRC.forEach((it) => {
    if (it.dot) {
      strokes.push({ dot: { x: it.dot[0], y: it.dot[1], r: it.dot[2] }, len: 30, pts: [] }); total += 30;
      all.push({ x: it.dot[0] - it.dot[2], y: it.dot[1] - it.dot[2] }, { x: it.dot[0] + it.dot[2], y: it.dot[1] + it.dot[2] });
      return;
    }
    const st = { pts: [], len: 0, dot: null };
    it.p.forEach((q) => {
      const p = { x: q[0], y: q[1], w: q[2], c: 0 };
      if (st.pts.length) { const l = st.pts[st.pts.length - 1]; st.len += Math.hypot(p.x - l.x, p.y - l.y); }
      p.c = st.len; st.pts.push(p); all.push(p);
    });
    total += st.len; strokes.push(st);
  });
  const speed = total / 1900; let cur = 1500;   // 첫 획 시작 시각(ms): 그 전까지는 마법진만 먼저 그려지기 시작한다 (인트로 전체 +1.15초)
  strokes.forEach((st) => { const dur = st.dot ? 140 : Math.max(120, st.len / speed); st.t0 = cur; st.t1 = cur + dur; cur = st.t1 + 110; });
  const T = { writeEnd: cur }; T.go = cur + 300; T.wrapDur = 2700; T.pt = T.go + T.wrapDur; T.burst = T.pt + 280;
  let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
  all.forEach((p) => { x0 = Math.min(x0, p.x); y0 = Math.min(y0, p.y); x1 = Math.max(x1, p.x); y1 = Math.max(y1, p.y); });
  return { strokes: strokes, T: T, b: { x: x0, y: y0, w: x1 - x0, h: y1 - y0, cx: (x0 + x1) / 2, cy: (y0 + y1) / 2 } };
}
